/**
 * `Cloudflare.Env` is generated by `wrangler types` from wrangler.jsonc (worker-configuration.d.ts,
 * written by the typecheck script and ignored by git), so a renamed binding, var or secret fails
 * the typecheck instead of failing at runtime. Vars and secrets are documented in wrangler.jsonc.
 * Only settings that are not in the config file are declared here.
 */
export interface Env extends Cloudflare.Env {
  /** Secret that signs guest passes (32+ random characters). Unset: a development key, with a warning. */
  PASS_SIGNING_KEY?: string;
  /** Secret for admin routes (private tally, month close), 16+ characters. Unset: admin routes stay closed. */
  ADMIN_KEY?: string;
  /** Optional JSON object of per-room caps, e.g. {"hub":80,"grove":40}. */
  ROOM_CAPS?: string;
  /** Local load testing only: trust X-Forwarded-For as the client address. Never set in production. */
  TRUST_FORWARDED_FOR?: string;
  /**
   * The store that sells tickets (C35): its myshopify domain and the custom app's Admin API token.
   * Unset: the store's webhooks are refused and nothing is copied to the store.
   */
  SHOPIFY_SHOP?: string;
  SHOPIFY_ADMIN_TOKEN?: string;
  /** The secret the store signs its webhooks with. Unset: every webhook is refused. */
  SHOPIFY_WEBHOOK_SECRET?: string;
}
